    cs: 'Cvičný hotel nevytváří platební odkaz. Odkaz by vedl ke skutečnému poskytovateli platebních služeb a host by mohl zaplatit skutečné peníze za cvičnou rezervaci.',
    fr: 'Un établissement de formation ne crée pas de lien de paiement. Le lien mènerait à un vrai prestataire de paiement, et un client pourrait payer de l’argent réel pour une réservation d’exercice.',
