    nb: 'En innsjekket gjest kan ikke legges uten rom. Velg det nye rommet direkte; er det opptatt, bytter begge gjestene rom.',
    pl: 'Zameldowanego gościa nie można odłożyć bez pokoju. Wybierz od razu nowy pokój; jeśli jest zajęty, obaj goście zamienią się pokojami.',
    cs: 'Ubytovaný host nejde do odkladiště. Vyber rovnou nový pokoj; je-li obsazený, oba hosté si pokoje vymění.',
    fr: 'Un client arrivé ne peut pas être mis en attente. Choisis directement la nouvelle chambre ; si elle est occupée, les deux clients échangent leurs chambres.',
    it: 'Un ospite arrivato non può essere messo in sospeso. Scegli direttamente la nuova camera; se è occupata, i due ospiti si scambiano le camere.',
