    sv: 'Betalleverantören kan inte nås just nu. Inget har ändrats; försök igen senare.',
    nb: 'Betalingsleverandøren er ikke tilgjengelig akkurat nå. Ingenting ble endret; prøv igjen senere.',
    cs: 'Poskytovatel platebních služeb je momentálně nedostupný. Nic nebylo změněno; zkuste to prosím později.',
