    es: 'El proveedor de pagos no está accesible en este momento. No se ha cambiado nada; vuelva a intentarlo más tarde.',
    ru: 'Платёжный провайдер сейчас недоступен. Ничего не изменено; пожалуйста, повторите позже.',
