    nb: 'Fakturaer er underlagt den skattemessige oppbevaringsfristen og fjernes ikke ved sletting.',
    cs: 'Faktury podléhají daňové archivační lhůtě a při výmazu se neodstraňují.',
    fr: 'Les factures sont soumises au délai de conservation fiscal et ne sont pas supprimées lors d’un effacement.',
    it: 'Le fatture sono soggette al termine di conservazione fiscale e non vengono rimosse con una cancellazione.',
